import{_ as t,o as a,a as r,b as i}from"./app.DKoEZOcr.js";const l=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C API","link":"/api/api_list"},{"text":"SIMD API","link":"/api/SIMD-API/SIMD-API"},{"text":"基础API","link":"/api/SIMD-API/basic_api/basic_api"},{"text":"Reg矢量计算","link":"/api/SIMD-API/basic_api/reg_vector_compute/reg_vector_compute"},{"text":"寄存器数据类型","link":"/api/SIMD-API/basic_api/reg_vector_compute/register_data_types/register_data_types"}]},"headers":[],"relativePath":"api/SIMD-API/basic_api/reg_vector_compute/register_data_types/register_data_types.md","filePath":"api/SIMD-API/basic_api/reg_vector_compute/register_data_types/register_data_types.md","lastUpdated":1787050286000}'),s={name:"api/SIMD-API/basic_api/reg_vector_compute/register_data_types/register_data_types.md"};function _(p,e,o,g,n,d){return a(),r("div",null,[...e[0]||(e[0]=[i('<div><article class="markdown-body"><h1>寄存器数据类型<span id="ZH-CN_TOPIC_0000001952211245"></span></h1><p>Reg矢量计算API操作的基础寄存器数据类型介绍如下：</p><ul><li><p><strong><a href="RegTensor.html">RegTensor</a></strong><br> 矢量数据寄存器，Reg矢量计算基本存储单元，用于矢量计算。RegTensor的位宽是VL（VectorLength），长度为256B，可存储VL/sizeof(T)个数据（T表示数据类型）。b64或complex32类型下，支持扩展存储2VL用于复杂计算。</p></li><li><p><strong><a href="MaskReg.html">MaskReg</a></strong><br> 掩码寄存器，用于矢量计算中选择参与计算的元素。MaskReg的位宽是VL/8，长度为32B。</p></li><li><p><strong><a href="UnalignRegForLoad-UnalignRegForStore.html">UnalignRegForLoad &amp; UnalignRegForStore</a></strong><br> 非对齐寄存器，作为缓冲区，用来优化Unified Buffer（UB）和RegTensor之间的连续非对齐地址访问的开销。</p></li><li><p><strong><a href="AddrReg.html">AddrReg</a></strong><br> 地址寄存器，用于存储地址偏移量的寄存器。AddrReg通过调用CreateAddrReg接口根据每层循环所设置的stride进行地址偏移自增。</p></li></ul></article></div>',1)])])}const I=t(s,[["render",_]]);export{l as __pageData,I as default};
